import {
  selectAmbiguousMonomersInCategory,
  selectFilteredMonomers,
} from 'state/library';
import { MonomerGroups } from '../../../../constants';
import { Summary } from './Summary';
import { Icon, type MacromoleculesIconName } from 'src/uiBridge';

import {
  recalculateRnaBuilderValidations,
  RnaBuilderItem,
  RnaBuilderPresetsItem,
  selectActiveMonomerKey,
  selectFilteredPresets,
  selectIsActivePresetNewAndEmpty,
  selectIsEditMode,
  selectPresetPhosphateFilter,
} from 'state/rna-builder';
import {
  DetailsContainer,
  DisabledArea,
  StyledAccordion,
  StyledAccordionWrapper,
  NewPresetButton,
  PresetToolbar,
  PresetsScrollArea,
  FilterIconButton,
} from './styles';
import { PresetPhosphateFilterPopup } from './PresetPhosphateFilterPopup';
import { RnaPresetGroup } from 'components/monomerLibrary/RnaPresetGroup/RnaPresetGroup';
import { MonomerGroup } from 'components/monomerLibrary/monomerLibraryGroup';
import { memo, useEffect, useState } from 'react';
import { useDispatch } from 'react-redux';
import { useAppSelector } from 'hooks';
import { RnaElementsViewProps } from './types';
import { IRnaPreset } from 'ketcher-core';

type Props = RnaElementsViewProps & {
  newPreset: IRnaPreset;
};

const RnaElementsAccordionView = ({
  activeRnaBuilderItem,
  groupsData,
  newPreset,
  onNewPresetClick,
  onSelectItem,
  duplicatePreset,
  editPreset,
  libraryName,
}: Props) => {
  const dispatch = useDispatch();
  const presets = useAppSelector(selectFilteredPresets);
  const monomers = useAppSelector(selectFilteredMonomers);
  const isEditMode = useAppSelector(selectIsEditMode);
  const isActivePresetNewAndEmpty = useAppSelector(
    selectIsActivePresetNewAndEmpty,
  );
  const activeMonomerKey = useAppSelector(selectActiveMonomerKey);
  const presetPhosphateFilter = useAppSelector(selectPresetPhosphateFilter);
  // The filter icon shows a small indicator dot whenever the current filter
  // state differs from the default ("all options off"), per spec.
  const isFilterActive = Boolean(
    presetPhosphateFilter?.fivePrime ||
      presetPhosphateFilter?.threePrime ||
      presetPhosphateFilter?.noPhosphate,
  );

  const [expandedAccordion, setExpandedAccordion] =
    useState<RnaBuilderItem | null>(activeRnaBuilderItem);
  const [isFilterOpen, setIsFilterOpen] = useState(false);

  const handleAccordionSummaryClick = (rnaBuilderItem: RnaBuilderItem) => {
    if (expandedAccordion === rnaBuilderItem) {
      setExpandedAccordion(null);
    } else {
      setExpandedAccordion(rnaBuilderItem);
      dispatch(
        recalculateRnaBuilderValidations({ rnaPreset: newPreset, isEditMode }),
      );
    }
  };

  useEffect(() => {
    setExpandedAccordion(activeRnaBuilderItem);
  }, [activeRnaBuilderItem]);

  return (
    <>
      {groupsData.map((groupData) => {
        const expanded = expandedAccordion === groupData.groupName;
        const variantMonomers = selectAmbiguousMonomersInCategory(
          monomers,
          groupData.groupName as MonomerGroups,
        );
        const quantity = [...groupData.groups, ...variantMonomers].reduce(
          (acc, group) => acc + (group.groupItems.length || 0),
          0,
        );
        const summary = (
          <Summary
            iconName={groupData.iconName as MacromoleculesIconName}
            groupName={groupData.groupName}
            quantity={quantity}
            expanded={expanded}
          />
        );
        const details =
          groupData.groupName === RnaBuilderPresetsItem.Presets ? (
            <DetailsContainer>
              <PresetToolbar>
                <NewPresetButton
                  onClick={onNewPresetClick}
                  data-testid="new-preset-button"
                >
                  Add new
                </NewPresetButton>
                <FilterIconButton
                  type="button"
                  active={isFilterOpen}
                  hasIndicator={isFilterActive}
                  onClick={(event) => {
                    event.stopPropagation();
                    setIsFilterOpen((prev) => !prev);
                  }}
                  aria-label="Filter presets by phosphate position"
                  data-testid="preset-filter-button"
                >
                  <Icon name="filter" />
                </FilterIconButton>
                {isFilterOpen && (
                  <PresetPhosphateFilterPopup
                    onClose={() => setIsFilterOpen(false)}
                  />
                )}
              </PresetToolbar>
              <PresetsScrollArea>
                <RnaPresetGroup
                  duplicatePreset={duplicatePreset}
                  editPreset={editPreset}
                  presets={presets}
                />
              </PresetsScrollArea>
              {isEditMode && !isActivePresetNewAndEmpty && <DisabledArea />}
            </DetailsContainer>
          ) : (
            <DetailsContainer>
              <>
                {groupData.groups.map(({ groupItems, groupTitle }) => {
                  const shouldShowTitle = [
                    MonomerGroups.BASES,
                    MonomerGroups.NUCLEOTIDES,
                    MonomerGroups.PEPTIDES,
                  ].includes(groupData.groupName as MonomerGroups);

                  return (
                    <MonomerGroup
                      key={groupTitle}
                      title={shouldShowTitle ? groupTitle : undefined}
                      groupName={groupData.groupName}
                      items={groupItems}
                      selectedMonomerUniqueKey={activeMonomerKey}
                      onItemClick={(monomer) =>
                        onSelectItem(monomer, groupData.groupName)
                      }
                    />
                  );
                })}
                {variantMonomers.map((group) => (
                  <MonomerGroup
                    key={group.groupTitle}
                    title={group.groupTitle}
                    items={group.groupItems}
                    libraryName={libraryName}
                    selectedMonomerUniqueKey={activeMonomerKey}
                    onItemClick={(monomer) =>
                      onSelectItem(monomer, groupData.groupName)
                    }
                  />
                ))}
              </>
            </DetailsContainer>
          );
        return groupData.groupName === RnaBuilderPresetsItem.Presets &&
          expanded ? (
          <StyledAccordionWrapper key={groupData.groupName}>
            <StyledAccordion
              data-testid="styled-accordion"
              dataTestIdDetails={`rna-accordion-details-${groupData.groupName}`}
              summary={summary}
              details={details}
              expanded={expanded}
              onSummaryClick={() =>
                handleAccordionSummaryClick(groupData.groupName)
              }
            />
          </StyledAccordionWrapper>
        ) : (
          <StyledAccordion
            key={groupData.groupName}
            data-testid="styled-accordion"
            dataTestIdDetails={`rna-accordion-details-${groupData.groupName}`}
            summary={summary}
            details={details}
            expanded={expanded}
            onSummaryClick={() =>
              handleAccordionSummaryClick(groupData.groupName)
            }
          />
        );
      })}
    </>
  );
};

export default memo(RnaElementsAccordionView);
